import{_ as a,o as t,c as o,a7 as i}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Birthday Buddy Data Collection","description":"Official data-collection information for Birthday Buddy.","frontmatter":{"title":"Birthday Buddy Data Collection","description":"Official data-collection information for Birthday Buddy.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/birthday-buddy.md","filePath":"data-collection/birthday-buddy.md"}'),r={name:"data-collection/birthday-buddy.md"};function n(d,e,s,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="birthday-buddy-data-collection" tabindex="-1">Birthday Buddy Data Collection <a class="header-anchor" href="#birthday-buddy-data-collection" aria-label="Permalink to &quot;Birthday Buddy Data Collection&quot;">​</a></h1><p><strong>Last Updated:</strong> August 26, 2026</p><p>Birthday Buddy is designed to keep reminder information on your device. It does not require an account, display ads, include analytics, or send app usage telemetry to the developer.</p><h2 id="data-you-may-add" tabindex="-1">Data you may add <a class="header-anchor" href="#data-you-may-add" aria-label="Permalink to &quot;Data you may add&quot;">​</a></h2><p>The app can locally store:</p><ul><li>Names, birthdays, anniversaries, custom occasions, notes, and favourites</li><li>Optional profile photos</li><li>Reminder timing and notification-privacy preferences</li><li>Optional links to Android contacts and contact-sync choices</li><li>Theme, accessibility, app-lock, and other settings</li><li>Encrypted backup content when you explicitly export a backup</li></ul><h2 id="optional-device-sources" tabindex="-1">Optional device sources <a class="header-anchor" href="#optional-device-sources" aria-label="Permalink to &quot;Optional device sources&quot;">​</a></h2><ul><li><strong>Contacts:</strong> an individual contact picker or an opt-in, preview-first sync can read supported names, photos, and date events. Processing happens locally, and Birthday Buddy never writes to contacts.</li><li><strong>Camera and photos:</strong> only the image you capture or select is copied into app-local data.</li><li><strong>Notifications:</strong> locally scheduled reminders contain wording determined by your lock-screen privacy setting.</li><li><strong>Biometrics:</strong> Android performs authentication. The app receives an authentication result, not your biometric template.</li></ul><h2 id="storage-and-transmission" tabindex="-1">Storage and transmission <a class="header-anchor" href="#storage-and-transmission" aria-label="Permalink to &quot;Storage and transmission&quot;">​</a></h2><p>Android data is stored in app-local SQLite storage and protected preferences. Browser data is stored locally by the browser, including IndexedDB. Birthday Buddy does not automatically transmit personal reminder data to a developer-operated server.</p><p>An encrypted <code>.ocbackup</code> file leaves app-local storage only when you export it. Files and links you send to another service are then handled by that destination. Visiting the GitHub Pages-hosted browser app or Google Play can expose ordinary request or store activity information to those providers under their own policies.</p><h2 id="data-received-by-the-developer" tabindex="-1">Data received by the developer <a class="header-anchor" href="#data-received-by-the-developer" aria-label="Permalink to &quot;Data received by the developer&quot;">​</a></h2><p>The developer receives no app data automatically. If you contact support, the developer receives the email address, message, and attachments you choose to send and uses them to respond.</p><p>For permission-specific details, including contacts, camera, notifications, reboot, wake lock, exact alarms, vibration, biometrics, legacy fingerprint compatibility, and internet access, see the Birthday Buddy Privacy Policy.</p>',14)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
